import{_ as i,l as n,o as e,c as s,v as r,p as l,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"排序归并连接","description":"","frontmatter":{"title":"排序归并连接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sort-merge-join.md","filePath":"cs/sort-merge-join.md","lastUpdated":1789023840000}'),c={name:"cs/sort-merge-join.md"};function E(_,a,m,B,f,u){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="排序归并连接" tabindex="-1">排序归并连接 <a class="header-anchor" href="#排序归并连接" aria-label="Permalink to &quot;排序归并连接&quot;">​</a></h1><div class="epigraph"><p>两侧按连接键排序后，像归并两个有序表一样推进指针；等值与某些范围连接都自然。</p><footer>—— 据 Blasgen and Eswaran；Ramakrishnan and Gehrke；对照外存排序</footer></div><p><a href="/cs/nlj-hash-join">上一课</a>收了嵌套循环与哈希。本课不重做分区哈希。缺口是第三种形状：输入若已按键有序（B+ 叶扫描、聚簇），或付得起外存排序，归并连接一次扫过。它也服务非哈希友好的条件。下一课才把算子收成计划树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>哈希要求等值且能选哈希函数。<a href="/cs/insertion-merge">外存排序</a> 课已有归并。连接：两路归并时，键相等则做笛卡尔（在重复组内），然后前进较小的一侧。预排序代价高，但输出自然有序，可能帮下一算子。缺口是<strong>有序归并这一物理合同</strong>。</p><p><span class="marginnote">重复键组很大时，归并要能把一组物化或回绕，否则漏配。这是实现细节，规格仍是代数连接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>若无序：外部排序两侧（或一侧），再归并。若一侧是有序索引扫描，只排另一侧。内存中可用替换选择产生初始顺串。本课不把并行排序的采样划分写完。</p>',8)),(e(),l(p,null,{default:t(()=>[h(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%B8%A4%E4%BE%A7%E8%BE%93%E5%85%A5%22%5D%20--%3E%20SORT%5B%22%E6%8C%89%E8%BF%9E%E6%8E%A5%E9%94%AE%E6%8E%92%E5%BA%8F%22%5D%0A%20%20SORT%20--%3E%20MG%5B%22%E5%BD%92%E5%B9%B6%E7%9B%B8%E7%AD%89%E9%94%AE%E7%BB%84%22%5D%0A%20%20IDX%5B%22%E5%B7%B2%E6%9C%89%E5%BA%8F%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20MG%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>归并把随机 I/O 换成顺序 I/O，和<a href="/cs/locality-principle">局部性</a> 一致。与哈希对照：哈希探测是随机桶访问；归并是顺序。优化器后课用页数模型比较三者，而不是「哈希总是更快」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 zigzag 连接当主干必选。如何把选择、连接、扫描排成树并交给执行器，下一课查询计划。</p><p>后课默认：三种物理连接都可用。执行的对象是计划树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>排序归并对有序或可排序输入一次扫描。</li><li>输出有序可能被后续算子利用。</li><li>计划树下一课。</li><li>出处：Blasgen and Eswaran；Ramakrishnan and Gehrke。</li></ul>',7))])}const g=i(c,[["render",E]]);export{T as __pageData,g as default};
